import 'package:flutter/material.dart';
import '../../core/network/api_client.dart';
import '../../core/auth/session_store.dart';
import '../../core/booking/driver_finance_repository.dart';
class DriverEarningsScreen extends StatefulWidget {const DriverEarningsScreen({super.key});@override State<DriverEarningsScreen> createState()=>_DriverEarningsScreenState();}
class _DriverEarningsScreenState extends State<DriverEarningsScreen>{late final DriverFinanceRepository repo;Map<String,dynamic>? data;String? error;bool busy=false;@override void initState(){super.initState();repo=DriverFinanceRepository(ApiClient(SessionStore()));load();}Future<void> load()async{setState((){busy=true;error=null;});try{data=await repo.load();}catch(e){error=e.toString();}if(mounted)setState(()=>busy=false);}double numv(dynamic v)=>double.tryParse('$v')??0;String pkr(dynamic v)=>'PKR ${numv(v).toStringAsFixed(0)}';@override Widget build(BuildContext context){final wallet=Map<String,dynamic>.from((data?['wallet']??{}) as Map);final entries=((data?['entries']??[]) as List).cast<Map<String,dynamic>>();return SafeArea(child:RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.all(18),children:[const Text('Earnings & wallet',style:TextStyle(fontSize:24,fontWeight:FontWeight.w800)),const SizedBox(height:14),if(busy&&data==null)const Center(child:CircularProgressIndicator()),if(error!=null)Card(child:Padding(padding:const EdgeInsets.all(16),child:Text(error!))),if(data!=null)...[Card(child:Padding(padding:const EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Available balance'),const SizedBox(height:6),Text(pkr(wallet['availableBalance']),style:const TextStyle(fontSize:28,fontWeight:FontWeight.w900)),const Divider(),Row(children:[Expanded(child:Text('Pending\n${pkr(wallet['pendingBalance'])}')),Expanded(child:Text('Paid\n${pkr(wallet['paidBalance'])}'))])]))),const SizedBox(height:10),FilledButton.icon(onPressed:busy?null:()=>payout(wallet),icon:const Icon(Icons.account_balance),label:const Text('Request payout')),const SizedBox(height:18),const Text('Wallet activity',style:TextStyle(fontSize:18,fontWeight:FontWeight.w800)),...entries.map((e)=>Card(child:ListTile(leading:Icon(numv(e['amount'])>=0?Icons.add_circle_outline:Icons.remove_circle_outline),title:Text('${e['description']}'),subtitle:Text('${e['entryType']} • ${e['createdAt']}'),trailing:Text(pkr(e['amount']),style:const TextStyle(fontWeight:FontWeight.w700))))]]])));}Future<void> payout(Map<String,dynamic>wallet)async{final c=TextEditingController();final amount=await showDialog<double>(context:context,builder:(ctx)=>AlertDialog(title:const Text('Request payout'),content:TextField(controller:c,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Amount (PKR)')),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(ctx,double.tryParse(c.text)),child:const Text('Submit'))]));if(amount==null)return;setState(()=>busy=true);try{await repo.requestPayout(amount:amount,method:'BankTransfer',version:(wallet['version']??1) as int);if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Payout request submitted')));await load();}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}finally{if(mounted)setState(()=>busy=false);}}}
